import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import './QuestionList.css';
import HomeIcon from '../Common/HomeIcon';
import QuestionFilter from './QuestionFilter';


function QuestionList() {
  const [questions, setQuestions] = useState([]);
  const [filterText, setFilterText] = useState('');


  useEffect(() => {
    fetch('http://localhost:8080/questions')
      .then(res => res.json())
      .then(data => setQuestions(data))
      .catch(err => console.error('Eroare:', err));
  }, []);

  return (
    <div className="question-list-container">
      <HomeIcon />
      <h2>Întrebări</h2>
      {questions.map((q) => (
        <div key={q.id} className="question-item">
          <h3>{q.title}</h3>
          <p><strong>Autor:</strong> {q.user.username}</p>
          <p><strong>Etichete:</strong> {q.questionTags.map(tag => (
            <span className="tag" key={tag.id}>{tag.tag.name}</span>
          ))}</p>

          <Link to={`/questions/${q.id}`}>
            <button className="see-question-btn">Vezi întrebarea și răspunsurile</button>
          </Link>
        </div>
      ))}
    </div>
  );
}

export default QuestionList;
